import { readFileSync } from "node:fs";

import openapiTS, { astToString } from "openapi-typescript";
import { format, resolveConfig } from "prettier";

const spec = new URL("../../crates/saka-api/openapi.json", import.meta.url);
const target = new URL("../src/api/schema.d.ts", import.meta.url);
const generated = astToString(await openapiTS(spec));
const header =
  "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n";
const options = (await resolveConfig(target.pathname)) ?? {};
const expected = await format(header + generated, {
  ...options,
  parser: "typescript",
});
const committed = readFileSync(target, "utf8");
if (committed !== expected) {
  process.stderr.write(
    "src/api/schema.d.ts is out of date; run `pnpm api:generate`\n",
  );
  process.exit(1);
}
